package br.com.inframonitor.security;
import br.com.inframonitor.common.api.ErroResposta; import tools.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.http.MediaType; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import java.io.IOException;
@Component public class ApiAccessDeniedHandler implements AccessDeniedHandler { private final ObjectMapper mapper; public ApiAccessDeniedHandler(ObjectMapper mapper){this.mapper=mapper;} public void handle(HttpServletRequest r,HttpServletResponse s,AccessDeniedException e)throws IOException{s.setStatus(403);s.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(s.getOutputStream(),ErroResposta.de(403,"Forbidden","FORBIDDEN","Acesso negado",r.getRequestURI()));} }
